def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_prime_power(n):
    if n <= 0:
        return False

    # Check for prime powers p^k, k >= 1

    # Case k=1: n is prime
    if is_prime(n):
        return True

    # Case k >= 2: n = p^k
    for p in range(2, int(n**0.5) + 2):
        if is_prime(p):
            # Check if n is a power of p
            temp = n
            while temp > 1 and temp % p == 0:
                temp //= p
            if temp == 1:
                return True

    # Handle the case where n itself is a prime power, but its base p > sqrt(n).
    # Since we checked all primes up to sqrt(n), if n is composite, it must have a factor <= sqrt(n).
    # If n is a prime power p^k, and p > sqrt(n), then k must be 1, which is covered by the prime check.
    # However, let's verify the structure if we use logs.

    # A more robust check: iterate through primes p, and see if p^k = n for some k>=1.
    for p in range(2, n + 1):
        if is_prime(p):
            if n > 0 and (n & (n - 1) == 0 and p == 2): # check power of 2 efficiently (though we are iterating p)
                 pass # covered by loop below if n is power of 2

            power = 1
            while power <= n:
                if power == n:
                    return True
                power *= p
    return False

# Re-implementing is_prime_power based on the standard definition to be safe.
def is_prime_power_standard(n):
    if n <= 0:
        return False
    if n == 1: # 1 is generally not considered a prime power based on k>=1, but 2^0=1. Let's assume k>=1.
        return False 

    i = 2
    while i * i <= n:
        if n % i == 0:
            # i is a factor. Check if n is entirely composed of factors of i.
            temp = n
            while temp > 0 and temp % i == 0:
                temp //= i

            if temp == 1:
                return True
            else:
                # n has at least two distinct prime factors (i and the factors of temp)
                return False
        i += 1

    # If loop finishes, n must be prime itself. Primes are prime powers (p^1).
    return True

